// Native V17 real ZSTD Parquet smoke. The fixture is generated by
// v30-parquet-fixture.py in CI with OpenThoughts3's nested
// conversations=[{from:"human",value:...},{from:"gpt",value:...}] schema.
import test from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import fsp from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import {Brain} from "../transcend/torus-aether/devour/brain.mjs";
import {makeMaze,seedOf,SEEDS} from "../transcend/torus-aether/worlds/labyrinth.mjs";
import {playExercise,KIND} from "../transcend/torus-aether/worlds/exercise.mjs";
import {openTextDataset} from "../transcend/torus-aether/data/text-dataset.mjs";
import {NativeAtlasRuntime} from "../research/text-hypermaze/native-atlas-server.mjs";
import {ingestNativeParquet} from "../research/text-hypermaze/native-parquet-ingest.mjs";

const root=process.env.V30_TEST_PARQUET;
if(!root)throw Error("V30_TEST_PARQUET must point to actual generated nested ZSTD Parquet");
const rules={depth:1,off:["R2","R4"],budEvery:100,empty:true,maxWires:32,fold:false};
function nativeBrain(){
 const b=new Brain({rules,seed:11});
 for(let i=0;i<240;i++){
  playExercise(makeMaze(seedOf(SEEDS.train,500+i*23),[7,9,11][i%3]),b.disc);
  if(i>=24&&b.disc.attract(KIND.target)>.2&&b.disc.conduct(KIND.floor)>=.5)break;
 }
 assert.ok(b.disc.attract(KIND.target)>.2);
 return b;
}
test("V30 actual nested conversations Parquet, real ZSTD reader and excluded 16 heldout",async()=>{
 const ds=await openTextDataset(root);
 assert.equal(ds.total,82);
 assert.equal(ds.trainRows,66);
 assert.equal(ds.held,16);
 const first=await ds.exercise(0),lastTrain=await ds.exercise(65);
 const firstHeld=await ds.heldOut(0),lastHeld=await ds.heldOut(15);
 assert.match(first.prompt,/planet number 0 feels cold/);
 assert.match(first.answer,/planet number 0 feels warm/);
 assert.match(lastTrain.prompt,/metal number 65 feels cold/);
 assert.match(firstHeld.prompt,/Alice has 66 books/);
 assert.match(lastHeld.prompt,/metal number 81 feels cold/);
 assert.equal(firstHeld.index,66);
 assert.equal(lastHeld.index,81);
 console.log("V30_NESTED_PARQUET_DECODER_PASS",JSON.stringify({
  rows:ds.total,trainRows:ds.trainRows,heldout:ds.held,
  realCompression:"ZSTD",nestedHumanGPTDecoded:true
 }));
});
test("V30 genuine original Brain Parquet 30→66 resume and fingerprint safety, no heldout exposure",async(t)=>{
 const tmp=await fsp.mkdtemp(path.join(os.tmpdir(),"mp-v30-real-parquet-"));
 t.after(()=>fsp.rm(tmp,{recursive:true,force:true}));
 const b=nativeBrain();
 const source=path.join(tmp,"original-before-v30.v8");
 b.save(source);const original=await fsp.readFile(source);
 const runtime=new NativeAtlasRuntime(Brain.load(source),{
  out:path.join(tmp,"checkpoint-v30"),maxStates:48,maxDepth:3});
 const start=await ingestNativeParquet(runtime,root,{maxRows:30,saveEvery:10});
 assert.equal(start.rowsConsumed,30);
 assert.equal(start.heldoutExcluded,16);
 assert.equal(start.completedAllTrainRows,false);
 assert.equal(runtime.status().mode,"partial");
 assert.equal(runtime.status().realOpenThoughtsParquet.cursor,30);
 assert.equal(runtime.status().realOpenThoughtsParquet.lastSavedCursor,30);
 assert.ok(runtime.status().originalNativeText.observations>0);
 assert.ok(runtime.status().originalNativeText.learnedTextContrastOperators>0);
 const firstDigest=await fsp.readFile(source);
 assert.deepEqual(firstDigest,original,"Original trained V17 checkpoint is READ ONLY");
 const restored=new NativeAtlasRuntime(Brain.load(runtime.checkpoint),{
  out:runtime.out,maxStates:48,maxDepth:3});
 assert.equal(restored.status().realOpenThoughtsParquet.cursor,30,
  "Persisted native Brain cursor must be EXACT");
 const sourceStats=restored.brain.observedTransformations.seen;
 assert.ok(sourceStats>0);
 const rest=await ingestNativeParquet(restored,root,{maxRows:0,saveEvery:11});
 assert.equal(rest.rowsConsumed,66);
 assert.equal(rest.heldoutExcluded,16);
 assert.equal(rest.completedAllTrainRows,true);
 assert.equal(restored.status().mode,"finished");
 assert.equal(restored.status().realOpenThoughtsParquet.cursor,66);
 assert.equal(restored.status().realOpenThoughtsParquet.lastSavedCursor,66);
 assert.ok(restored.brain.observedTransformations.seen>=sourceStats);
 assert.ok(restored.status().originalNativeText.learnedTextContrastOperators>0);
 assert.equal(restored.engine.summary().reusableActions,0,
  "Corpus contrast operators must NOT magically become physical world actions");
 assert.equal(restored.atlas.summary().nativeTextContrastsUsedAsPhysicalActions,false);
 const known=restored.atlas.globalTopology({nodeLimit:1000,edgeLimit:2000});
 assert.ok(known.nativeTextStatesStillActive>0);
 assert.ok(known.nativeTextContrastRules>0);
 assert.equal(known.witnessedPhysicalEdges,0);
 assert.ok(known.textContrastEdges>0);
 assert.equal(known.unknownLanguageSpaceNotEnumerated,true);
 assert.deepEqual(await fsp.readFile(source),original);
 const revived=new NativeAtlasRuntime(Brain.load(restored.checkpoint),{
  out:restored.out});
 assert.equal(revived.status().realOpenThoughtsParquet.cursor,66);
 await assert.rejects(ingestNativeParquet(revived,root,
  {saveEvery:3,maxRows:60}),/lower than saved/);
 const finalRows=await ingestNativeParquet(revived,root,
  {saveEvery:3,maxRows:0});
 assert.equal(finalRows.rowsConsumed,66);
 assert.equal(revived.status().realOpenThoughtsParquet.cursor,66);
 console.log("V30_REAL_PARQUET_NATIVE_RESUME_PASS",JSON.stringify({
  actualZstdParquetRowsConsumed:rest.rowsConsumed,
  heldoutRowsNeverLearned:rest.heldoutExcluded,
  resumedFromPersistedCursor:30,
  originalBrainCheckpointByteIdentical:true,
  originalNativeTextOperators:revived.brain.observedTransformations.operators.size,
  activeCorpusStates:revived.brain.observedTransformations.records.size,
  globalAtlasContrastEdges:known.textContrastEdges,
  actualSemanticAnsweringNotEstablished:true
 }));
});
